FourDTypeID RW_TextToFourDTypeID (PA_PluginParameters params, int index)
{
	sBuf = PA_GetStringParameter (params, index);
	PA_Unichar*	p = PA_GetUnistring (sBuf);
	long		l = PA_GetUnistringLength (sBuf);
	return RW_TextToFourDTypeID (p , l);
}


FourDTypeID RW_TextToFourDTypeID (PA_Unichar* p, long l)
{
	OSType		result = '    ';

	if (l > 4)
		l = 4;
	while (l > 0 && *p >= ' ' && *p <= 255)
	{
		result = (result << 8) | (*p & 0xFF);
		p++;
		l--;
	}

	return result;
}


PA_Unichar* RW_FourDTypeIDToText (OSType l)
{
	static	PA_Unichar	r [5];

	r [4] = 0;
	int	i;
	for (i = 4; l != 0 && i-- > 0; )
	{
		r [i] = l & 0xff;
		l >>= 8;
	}

	return &r [i];
}


