void InitPlugin (void)
{
# if	_USE_MAC_API_
	gMyResFile = ::CurResFile();
# endif

//	PA_UseCStrings();
//	PA_ReturnNullTerminatedText (false);


#ifdef	__DEBUGMEM_H

	// DebugMemTurnOptionsOn (dgbmemOptDontFreeBlocks);
	DebugMemForgetLeaks();
	DebugMemReadLeaks ("rw.log");
#endif

#if	WINVER__
   // Initialize GDI+.
   Gdiplus::GdiplusStartupInput gdiplusStartupInput;
   Gdiplus::GdiplusStartup (&sGdiplusToken, &gdiplusStartupInput, NULL);
#endif

	RW_SetLicense (RWString());
}


void DeinitPlugin (void)
{
#if	WINVER__
   // Terminate GDI+.
   Gdiplus::GdiplusShutdown (sGdiplusToken);
#endif

#ifdef	__DEBUGMEM_H
# if	__MWERKS__ && !__MACH__
	__close_all();
# endif


#if !VERSIONWIN
	UTEC::Free();
#endif

	size_t	leaks = DebugMemReportLeaks ("rw.log");
	if (leaks != 0)
	{
		printf ("\nLeaked memory: %ld bytes\n", (long) leaks);
		fflush (stdout);
	}
#endif
}



long RW_OpenSession (long &outSession, long dstFlags, CText &dst, CText &inTemplate, CText &job, CText &inPrinter)	//mbs 25072011	printer
{
	RWPageComposer	*session = NULL;
	//mbs 08102010	needs to parse report template BEFORE opening the session!!!
	//mbs 19012011	needs to set job name BEFORE opening the session!!!
	long	result = RWPageComposer::OpenSession (session, dstFlags, inTemplate, dst, job, inPrinter);	//mbs 25072011	printer
    if(session != NULL)
        outSession = session->GetInternalID();
    else
        outSession = 0;
	return result;
}


long RW_CloseSession (long &ioSession)
{
	RWPageComposer	*session = RWPageComposer::GetSessionObject (ioSession);
	if (session == NULL)
		return errInvalidSessionRef;
	RWPageComposer::CloseSession (session);
	ioSession = 0;
	return noErr;
}


# define	IsFileName	((inOptions & 0x1) != 0)

// ---------------------------------------------------------------------------
// LoadSourceXML
// ---------------------------------------------------------------------------
// A report comes as a 4D document path (inIsFileName) or as XML text.

static	long	LoadSourceXML (RWXmlDocument &outXML, const CText &inSource, bool inIsFileName)
{
	RWXmlResult	result = inIsFileName ? outXML.LoadFile (RWStr::NativePath (inSource)) : outXML.LoadString (inSource);
	if (!result)
	{
		if (inIsFileName)
			printf ("Could not load file '%s'. Error='%s'.\n", RWStr::ToUTF8 (RWStr::NativePath (inSource)).c_str(), RWStr::ToUTF8 (result.description).c_str());
		else
			printf ("Could not load XML. Error='%s' at offset %ld.\n", RWStr::ToUTF8 (result.description).c_str(), (long) result.offset);
		fflush (stdout);
		return errCantLoadXML;
	}
	return noErr;
}

// source description for error messages: the path, or just "XML text"
static	std::string	SourceName (const CText &inSource, bool inIsFileName)
{
	return inIsFileName ? RWStr::ToUTF8 (RWStr::NativePath (inSource)) : std::string ("XML text");
}


long RW_Print (CText &src, long inOptions, long dstFlags, CText &dst, long inSession, CText &inPrinter)	//mbs 25072011	printer
{
	RWPageComposer	*session = NULL;
	if (inSession != 0)
	{
		session = RWPageComposer::GetSessionObject (inSession);
		if (session == NULL)
			return errInvalidSessionRef;
	}

	long					result = 0;

	try
	{
		RWXmlDocument	xml;
		result = LoadSourceXML (xml, src, IsFileName);

		if (result == noErr)
		{
			SRReportData					reportData (&xml);
			SRDataSource					reportSource;
			std::unique_ptr<RWXmlDocument>	printed;
			{
				SRReportWriter	reporter (reportSource, reportData, inOptions);
				printed = reporter.ReportToXML();
			}
			if (printed)
			{
				if (dstFlags & 0x10000000)	// debugging: keep the processed report next to the output
					(void) printed->SaveFile (RWStr::NativePath (dst) + u".rwxml");

				std::unique_ptr<RWPageComposer>	arwComposer;
				RWPageComposer	*pc = session;
				if (session == NULL)
				{
					pc = RWPageComposer::CreatePrinterComposer (dstFlags, dst, inPrinter);	//mbs 25072011	printer
					arwComposer.reset (pc);
				}
				else
					session->IncreaseBatchLevel();

				try
				{
					RWReportData		rwData (printed.get());
					RWReportWriter		rwReport (reportSource, rwData, *pc);
					rwReport.Report (NULL);
					result = rwReport.GetLastError();
					if (session != NULL)
						session->DecreaseBatchLevel();
				}
				catch (...)
				{
					if (session != NULL)
						session->DecreaseBatchLevel();
					throw;
				}
			}
		}
	}
	catch (long l)
	{
		printf ("\nException in RW_Print: %ld. Source: %s\n", l, SourceName (src, IsFileName).c_str());
		fflush (stdout);
		result = l;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_Print! Source: %s\n", SourceName (src, IsFileName).c_str());
		fflush (stdout);
		result = errGenericError;
	}

	return result;
}


long RW_Process_RW (CText &src, long inOptions, CText &dst)
{
	long	result = 0;

	try
	{
		RWXmlDocument	xml;
		result = LoadSourceXML (xml, src, IsFileName);

		if (result == noErr)
		{
			const RWString	path = RWStr::NativePath (dst);
			SRReportData	reportData (&xml);
			SRDataSource	reportSource;
			bool			saved = false;

			//mbs 05112010
			if ((inOptions & ~1) != 0)	// non-zero options (except path) means export
			{
				std::unique_ptr<RWXmlDocument>	printed;
				{
					SRReportWriter	reporter (reportSource, reportData, inOptions);
					printed = reporter.ReportToXML();
				}
				if (printed)
				{
					ETReportData	etData (printed.get());
					ETReport		etReport (reportSource, etData, inOptions);
					saved = etReport.ReportToFile (path);
				}
			}
			else
			{
				SRReportWriter					reporter (reportSource, reportData, inOptions);
				std::unique_ptr<RWXmlDocument>	printed = reporter.ReportToXML();
				saved = printed && printed->SaveFile (path);
			}

			if (!saved)
			{
				printf ("Could not create RW file '%s'. Error='%s'.\n", RWStr::ToUTF8 (path).c_str(), strerror (errno));
				fflush (stdout);
				result = errCantSaveXML;
			}
		}
	}
	catch (long l)
	{
		printf ("\nException in RW_Process_RW: %ld. Source: %s\n", l, SourceName (src, IsFileName).c_str());
		fflush (stdout);
		result = l;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_Process_RW! Source: %s\n", SourceName (src, IsFileName).c_str());
		fflush (stdout);
		result = errGenericError;
	}

	return result;
}


long RW_Print_RW (CText &src, long inOptions, long dstFlags, CText &dst, long inSession, CText &inPrinter)	//mbs 25072011	printer
{
	RWPageComposer	*session = NULL;
	if (inSession != 0)
	{
		session = RWPageComposer::GetSessionObject (inSession);
		if (session == NULL)
			return errInvalidSessionRef;
	}

	long	result = 0;

	try
	{
		RWXmlDocument	xml;
		result = LoadSourceXML (xml, src, IsFileName);

		if (result == noErr)
		{
			std::unique_ptr<RWPageComposer>	arwComposer;
			RWPageComposer	*pc = session;
			if (session == NULL)
			{
				pc = RWPageComposer::CreatePrinterComposer (dstFlags, dst, inPrinter);	//mbs 25072011	printer
				arwComposer.reset (pc);
			}
			else
				session->IncreaseBatchLevel();

			try
			{
				SRDataSourceProvider	reportSource;
				RWReportData			rwData (&xml);
				RWReportWriter			rwReport (reportSource, rwData, *pc);
				rwReport.Report (NULL);
				if (session != NULL)
					session->DecreaseBatchLevel();
			}
			catch (...)
			{
				if (session != NULL)
					session->DecreaseBatchLevel();
				throw;
			}
		}
	}
	catch (long l)
	{
		printf ("\nException in RW_Print_RW: %ld. Source: %s\n", l, SourceName (src, IsFileName).c_str());
		fflush (stdout);
		result = l;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_Print_RW! Source: %s\n", SourceName (src, IsFileName).c_str());
		fflush (stdout);
		result = errGenericError;
	}

	return result;
}


