long RW_CreateReport (long &outRepRef, CText &src, long inOptions)
{
	long		result = 0;
	DMReport	*rep = NULL;

	try
	{
		if (!src.empty())
		{
			RWXmlDocument	xml;
			result = LoadSourceXML (xml, src, IsFileName);
			if (result == noErr)
				rep = new DMReport (&xml);
		}
		else
			rep = new DMReport (NULL);
		outRepRef = rep ? rep->GetInternalID() : 0;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_CreateReport!\n");
		fflush (stdout);
		result = errGenericError;
		if (rep)
			delete rep;
	}

	return result;
}


long RW_ParseReport (long inRepRef, CText &src, long inOptions)
{
	long		result = 0;

	try
	{
		DMReport	*rep = DMReport::GetReportObject (inRepRef);
		if (rep == NULL)
			result = errInvalidReportRef;
		else if (!src.empty())
		{
			RWXmlDocument	xml;
			result = LoadSourceXML (xml, src, IsFileName);
			if (result == noErr)
				rep->SetReport (&xml);
		}
		else
			rep->SetReport (NULL);
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_ParseReport!\n");
		fflush (stdout);
		result = errGenericError;
	}

	return result;
}


// the report is written to the file src (inOptions bit 0), or returned in src as XML text
long RW_SaveReport (long inRepRef, CText &src, long inOptions)
{
	long		result = 0;

	try
	{
		DMReport	*rep = DMReport::GetReportObject (inRepRef);
		if (rep == NULL)
			result = errInvalidReportRef;
		else
		{
			RWXmlDocument	xml;
			rep->GetReport (xml);
			if (IsFileName)
			{
				const RWString	path = RWStr::NativePath (src);
				if (!xml.SaveFile (path))
				{
					printf ("Could not save file '%s'. Error='%s'.\n", RWStr::ToUTF8 (path).c_str(), strerror (errno));
					fflush (stdout);
					result = errCantSaveXML;
				}
			}
			else
				src = xml.SaveString (false, true);
		}
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_SaveReport!\n");
		fflush (stdout);
		result = errGenericError;
	}

	return result;
}
