long RW_GetProperties (PA_PluginParameters params)	// inRepRef, inRef, PA_Variable &ioProps, PA_Variable &ioValues);
{
	long		result = 0;
	DMReport	*rep = DMReport::GetReportObject (PA_GetLongParameter (params, 1));
	if (rep == NULL)
		result = errInvalidReportRef;
	else
	{
		long		inRef = PA_GetLongParameter (params, 2);
		DMBase		*obj = NULL;
		if (inRef != 0)
		{
			obj = rep->GetObject (inRef);
			if (obj == NULL)
				result = errInvalidObjectRef;
		}
		if (result == 0)
		{
			const DMBase::UserProps	*prs;
			PA_Variable	props = PA_GetVariableParameter (params, 3);
			PA_Variable	vals = PA_GetVariableParameter (params, 4);
			PA_Variable	names = PA_GetVariableParameter (params, 5);
			if (PA_GetVariableKind (props) != eVK_ArrayUnicode || PA_GetVariableKind (vals) != eVK_ArrayUnicode)
				result = errInvalidArrayType;
			else
			{
				int		i;
				long	count, realCount = 0;
				bool	useNames = (PA_GetVariableKind (names) == eVK_ArrayUnicode);
				if (obj == NULL)	// selected objects
				{
					std::unique_ptr<PSObjList>	l (rep->GetObjects (PSObjPropSelected));
					if (l->size() == 0)
						result = errInvalidObjectRef;
					else if (l->size() == 1)
						obj = static_cast <DMBase*> (*l->begin());
					else if (l->size() > 1)
					{
						obj = static_cast <DMBase*> (*l->begin());
						count = obj->GetUserProperties (prs);
						PSPropsMap	propsmap;
						RWValue	rv;
						for (i = 1; prs->id; prs++, i++)
						{
							if (static_cast <PSObject*> (obj)->GetProperty (prs->id, rv))
							{
								propsmap.SetProperty (prs->id, rv);
								realCount++;
							}
						}
						PSObjList::iterator		iter;
						OSType					id;
						for (iter = l->begin() + 1; iter != l->end(); iter++)
						{
							obj = static_cast <DMBase*> (*iter);
							count = obj->GetUserProperties (prs);
							for (i = 1; prs->id; prs++, i++)
							{
								if (static_cast <PSObject*> (obj)->GetProperty (prs->id, rv))
								{
									RWValue	mrv;
									if (propsmap.GetPropertyRef (prs->id, mrv))
									{
										if (mrv == rv)	// same value for this property?
											;	// nothing to do
										else
										{
											mrv.SetText (u"<multiple values>");
											propsmap.SetProperty (prs->id, mrv);
										}
									}
								}
								else if (propsmap.RemoveProperty (prs->id))
									realCount--;
							}
							PSPropsMap::reverse_iterator	rit;
							for (rit = propsmap.rbegin(); rit != propsmap.rend(); rit++)
							{
								id = (*rit).first;
								if (PSObject::FindPropertyByID (id, obj->GetProperties()) == NULL)
									if (propsmap.RemoveProperty (id))
										realCount--;
							}
						}

						obj = static_cast <DMBase*> (*l->begin());
						count = realCount;
						realCount = 0;
						PA_ResizeArray (&props, count);
						PA_ResizeArray (&vals, count);
						if (useNames)
							PA_ResizeArray (&names, count);
						count = obj->GetUserProperties (prs);
						for (i = 1; prs->id; prs++, i++)
						{
							if (propsmap.GetPropertyRef (prs->id, rv))
							{
								realCount++;
								RWTextValue	value;
								rv.GetTextValue (value, NULL);
								PA_Unistring	ustr = PA_CreateUnistring (RW_FourDTypeIDToText (prs->id));
								PA_SetStringInArray (props, realCount, &ustr);
								ustr = RWStr::CreatePA (value);
								PA_SetStringInArray (vals, realCount, &ustr);
								if (useNames)
								{
									const PSObject::PSObjProps *ps = PSObject::FindPropertyByID (prs->id, obj->GetProperties());
									if (ps && ps->name && *ps->name)
									{
										CText	n = RWStr::FromUTF8 (ps->name);
										ustr = RWStr::CreatePA (n);
									}
									else
										ustr = PA_CreateUnistring (RW_FourDTypeIDToText (prs->id));
									PA_SetStringInArray (names, realCount, &ustr);
								}
							}
						}
						if (realCount < count)
						{
							PA_ResizeArray (&props, realCount);
							PA_ResizeArray (&vals, realCount);
							if (useNames)
								PA_ResizeArray (&names, realCount);
						}
						PA_SetVariableParameter (params, 3, props, false);
						PA_SetVariableParameter (params, 4, vals, false);
						if (useNames)
							PA_SetVariableParameter (params, 5, names, false);
						obj = NULL;
					}
				}
				if (obj != NULL)	// this object
				{
					count = obj->GetUserProperties (prs);
					PA_ResizeArray (&props, count);
					PA_ResizeArray (&vals, count);
					if (useNames)
						PA_ResizeArray (&names, count);
					for (i = 1; prs->id; prs++, i++)
					{
						RWTextValue	value;
						if (static_cast <PSObject*> (obj)->GetProperty (prs->id, value))
						{
							realCount++;
							PA_Unistring	ustr = PA_CreateUnistring (RW_FourDTypeIDToText (prs->id));
							PA_SetStringInArray (props, realCount, &ustr);
							ustr = RWStr::CreatePA (value);
							PA_SetStringInArray (vals, realCount, &ustr);
							if (useNames)
							{
								const PSObject::PSObjProps *ps = PSObject::FindPropertyByID (prs->id, obj->GetProperties());
								if (ps && ps->name && *ps->name)
								{
									CText	n = RWStr::FromUTF8 (ps->name);
									ustr = RWStr::CreatePA (n);
								}
								else
									ustr = PA_CreateUnistring (RW_FourDTypeIDToText (prs->id));
								PA_SetStringInArray (names, realCount, &ustr);
							}
						}
					}
					if (realCount < count)
					{
						PA_ResizeArray (&props, realCount);
						PA_ResizeArray (&vals, realCount);
						if (useNames)
							PA_ResizeArray (&names, realCount);
					}
					PA_SetVariableParameter (params, 3, props, false);
					PA_SetVariableParameter (params, 4, vals, false);
					if (useNames)
						PA_SetVariableParameter (params, 5, names, false);
				}
			}
		}
	}

	return result;
}


long RW_SetProperties (PA_PluginParameters params)	// inRepRef, inRef, PA_Variable &inProps, PA_Variable &inValues);
{
	long		result = 0;
	DMReport	*rep = DMReport::GetReportObject (PA_GetLongParameter (params, 1));
	if (rep == NULL)
		result = errInvalidReportRef;
	else
	{
		long		inRef = PA_GetLongParameter (params, 2);
		DMBase		*obj = NULL;
		if (inRef != 0)
		{
			obj = rep->GetObject (inRef);
			if (obj == NULL)
				result = errInvalidObjectRef;
		}
		if (result == 0)
		{
			PA_Variable	props = PA_GetVariableParameter (params, 3);
			PA_Variable	vals = PA_GetVariableParameter (params, 4);
			if (PA_GetVariableKind (props) != eVK_ArrayUnicode || PA_GetVariableKind (vals) != eVK_ArrayUnicode)
				result = errInvalidArrayType;
			else
			{
				DMArea	*area = NULL;
				if (rep->GetPageComposer() != NULL)
					area = static_cast <DMArea*> (rep);
				int		i;
				long	count = PA_GetArrayNbElements (props);
				if (obj == NULL)	// selected objects
				{
					std::unique_ptr<PSObjList>	l (rep->GetObjects (PSObjPropSelected));
					if (l->size() == 0)
						result = errInvalidObjectRef;
					else if (l->size() == 1)
						obj = static_cast <DMBase*> (*l->begin());
					else if (l->size() > 1)
					{
						for (i = 1; i < count; i++)
						{
							PA_Unistring	ustr = PA_GetStringInArray (vals, i);
							RWValue			value;
							value.SetText (RWStr::FromPA (&ustr));
							ustr = PA_GetStringInArray (props, i);
							OSType	id = RW_TextToFourDTypeID (PA_GetUnistring (&ustr), PA_GetUnistringLength (&ustr));
							RWValue	oldrv;
							PSObjList::iterator	iter;
							for (iter = l->begin(); iter != l->end(); iter++)
							{
								obj = static_cast <DMBase*> (*iter);
								if (obj->GetProperty (id, oldrv))
								{
									if (obj->SetProperty (id, value))
									{
										if (area)
										{
											area->AddUndoProperty (obj, id, oldrv, value);
											if (obj->GetKind() == PSObject::eObject_Style)
												rep->GetPageComposer()->StyleChanged (static_cast <DMStyle*> (obj));
										}
									}
									else
										result = 1;
								}
								else
									result = 1;
							}
						}
						rep->Modified();
						obj = NULL;
					}
				}
				if (obj != NULL)	// this object
				{
					for (i = 1; i < count; i++)
					{
						PA_Unistring	ustr = PA_GetStringInArray (vals, i);
						RWValue			value;
						value.SetText (RWStr::FromPA (&ustr));
						ustr = PA_GetStringInArray (props, i);
						OSType	id = RW_TextToFourDTypeID (PA_GetUnistring (&ustr), PA_GetUnistringLength (&ustr));
						RWValue	oldrv;
						if (obj->GetProperty (id, oldrv))
						{
							if (obj->SetProperty (id, value))
							{
								if (area)
									area->AddUndoProperty (obj, id, oldrv, value);
							}
							else
								result = 1;
						}
						else
							result = 1;
					}
					if (area != NULL && obj->GetKind() == PSObject::eObject_Style)
						rep->GetPageComposer()->StyleChanged (static_cast <DMStyle*> (obj));
					rep->Modified();
				}
			}
		}
	}

	return result;
}


long RW_GetProperty (long inRepRef, long inRef, FourDTypeID id, PA_Pointer &ptr)
{
	long		result = 0;
	
	try
	{
		DMReport	*rep = DMReport::GetReportObject (inRepRef);
		if (rep == NULL)
			result = errInvalidReportRef;
		else
		{
			DMBase	*obj = rep->GetObject (inRef);
			if (obj == NULL)
				result = errInvalidObjectRef;
			else
			{
				PA_Variable	v = PA_GetPointerValue (ptr);
				RWValue		rv ((RWValue::PA_VariableKind) PA_GetVariableKind (v));
				if (obj->GetProperty (id, rv))
				{
					switch (PA_GetVariableKind (v))
					{
						case eVK_Unistring:
						{
							RWTextValue	tv;
							rv.GetTextValue (tv, NULL);
							PA_Unistring	uni = RWStr::CreatePA (tv);
							PA_SetStringVariable (&v, &uni);
							break;
						}
						case eVK_Real:
							if (rv.CoerceValue (RWValue::eValue_Real))
								PA_SetRealVariable (&v, rv.GetReal());
							else
								result = errInvalidPointerType;
							break;
						case eVK_Longint:
							if (rv.CoerceValue (RWValue::eValue_Integer))
								PA_SetLongintVariable (&v, rv.GetInteger());
							else
								result = errInvalidPointerType;
							break;
						case eVK_Boolean:
							if (rv.CoerceValue (RWValue::eValue_Boolean))
								PA_SetBooleanVariable (&v, rv.GetBoolean());
							else
								result = errInvalidPointerType;
							break;
						case eVK_Blob:
							if (rv.CoerceValue (RWValue::eValue_BLOB))
								PA_SetBlobVariable (&v, rv.GetBlobData(), rv.GetBlobSize());
							else
								result = errInvalidPointerType;
							break;
						case eVK_Picture:
							PA_SetPictureVariable (&v, SR4DData::Get4DPicture (rv));
							break;
						default:
							result = errInvalidPointerType;
							break;
					}
					PA_SetPointerValue (ptr, v);
				}
				else
					result = errGenericError;
			}
		}
	}
	catch (long err)
	{
		result = err;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_GetProperty!\n");
		fflush (stdout);
		result = errGenericError;
	}
	
	return result;
}


long RW_SetProperty (long inRepRef, long inRef, FourDTypeID id, PA_Pointer &ptr)
{
	long		result = 0;
	
	try
	{
		DMReport	*rep = DMReport::GetReportObject (inRepRef);
		if (rep == NULL)
			result = errInvalidReportRef;
		else
		{
			DMBase	*obj = NULL;
			if (inRef != 0)
			{
				obj = rep->GetObject (inRef);
				if (obj == NULL)
					result = errInvalidObjectRef;
			}
			if (result == 0)
			{
				OSType	trueID, thisID;
				bool	isStyleProperty = false;
				DMStyle	*st;
				DMArea	*area = NULL;
				if (rep->GetPageComposer() != NULL)
					area = static_cast <DMArea*> (rep);
				switch (id)
				{
					case PSObjPropRelPosTop:
					case PSObjPropRelPosLeft:
					case PSObjPropRelPosBottom:
					case PSObjPropRelPosRight:
					case PSObjPropRelMoveH:
					case PSObjPropRelMoveV:
						trueID = PSObjPropRect;
						break;
					case PSObjPropFontName:
					case PSObjPropSize:
					case PSObjPropStyleF:
					case PSObjPropStyleB:
					case PSObjPropStyleI:
					case PSObjPropStyleU:
					case PSObjPropStyleS:
					case PSObjPropWrap:
					case PSObjPropHorAlign:
					case PSObjPropVertAlign:
					case PSObjPropTextColor:
					case PSObjPropBackColor:
					case PSObjPropRotation:
					case PSObjPropBaseLineShift:
					case PSObjPropHorizontalScale:
					case PSObjPropLineSpacing:
						isStyleProperty = true;
						// fall through
					default:
						trueID = id;
						break;
				}
				if (obj == NULL)	// selected objects
				{
					std::unique_ptr<PSObjList>	l (rep->GetObjects (PSObjPropSelected));
					if (l->size() == 0)
						result = errInvalidObjectRef;
					else if (l->size() == 1)
						obj = static_cast <DMBase*> (*l->begin());
					else if (l->size() > 1)
					{
						PA_Variable	v = PA_GetPointerValue (ptr);
						RWValue		grv;
						switch (PA_GetVariableKind (v))
						{
							case eVK_Unistring:
							{
								PA_Unistring	uni = PA_GetStringVariable (v);
								grv.SetText (RWStr::FromPA (&uni));
								break;
							}
							case eVK_Real:
								grv.SetReal (PA_GetRealVariable (v));
								break;
							case eVK_Longint:
								grv.SetInteger (PA_GetLongintVariable (v));
								break;
							case eVK_Boolean:
								grv.SetBoolean (PA_GetBooleanVariable (v));
								break;
							case eVK_Blob:
							{
								SBlob	data;
								data.Init();
								data.fSize = PA_GetBlobVariable (v, data.fData);
								if (data.fSize > 0)
								{
									data.fData = malloc (data.fSize);
									data.fSize = PA_GetBlobVariable (v, data.fData);
								}
								grv.SetBlob (data, true);
								break;
							}
							case eVK_Picture:
//								SR4DData::GetPictureAsBlobFrom4D (PA_GetPictureVariable (v), grv);
								SR4DData::GetPictureFrom4D (PA_GetPictureVariable (v), grv, false);
								break;
							default:
								result = errInvalidPointerType;
								break;
						}
						PA_ClearVariable (&v);
						if (result == 0)
						{
							RWValue		rv;
							PSObjList::iterator	iter;
							for (iter = l->begin(); iter != l->end(); iter++)
							{
								obj = static_cast <DMBase*> (*iter);
								thisID = trueID;	//mbs 12102010	support for "cloned" Style
								if (isStyleProperty && obj->GetKind() >= PSObject::eObject_Text && (obj->GetKind() <= PSObject::eObject_Fld || obj->GetKind() == PSObject::eObject_TblHdr || obj->GetKind() <= PSObject::eObject_TblCol))
								{
									st = rep->GetStyle (static_cast <DMText*> (obj)->GetStyleID());
									if (st && st->GetFeatures() == 0)
									{
										st = NULL;
										thisID = PSObjPropStyle;
									}
									else if (area && st)
										area->AddUndoSnapshot (st, true);
								}
								else
									st = NULL;
								if (obj->GetProperty (thisID, rv))
								{
									RWValue		oldrv (rv);	//mbs 07122009	make a clone - Text/XMLText is by reference!!!
									if (obj->SetProperty (id, grv))
									{
										if (area != NULL)
										{
											if (obj->GetKind() == PSObject::eObject_Style)
												rep->GetPageComposer()->StyleChanged (static_cast <DMStyle*> (obj));
//											else if (st && st->GetFeatures())
//												rep->GetPageComposer()->StyleChanged (st);
											if (st)
												area->AddUndoSnapshot (st, false);
											else
											{
												if (thisID != id)
													obj->GetProperty (thisID, rv);
												area->AddUndoProperty (obj, thisID, oldrv, rv);
											}
										}
									}
									else
										result = 1;
								}
							}
							obj = NULL;
							rep->Modified();
						}
					}
				}
				if (obj != NULL)	// this object
				{
					RWValue		oldrv1;
					thisID = trueID;	//mbs 12102010	support for "cloned" Style
					if (isStyleProperty && obj->GetKind() >= PSObject::eObject_Text && (obj->GetKind() <= PSObject::eObject_Fld || obj->GetKind() == PSObject::eObject_TblHdr || obj->GetKind() <= PSObject::eObject_TblCol))
					{
						st = rep->GetStyle (static_cast <DMText*> (obj)->GetStyleID());
						if (st && st->GetFeatures() == 0)
						{
							st = NULL;
							thisID = PSObjPropStyle;
						}
						else if (area && st)
							area->AddUndoSnapshot (st, true);
					}
					else
						st = NULL;
					if (obj->GetProperty (thisID, oldrv1))
					{
						RWValue		oldrv (oldrv1);	//mbs 07122009	make a clone - Text/XMLText is by reference!!!
						PA_Variable	v = PA_GetPointerValue (ptr);
						RWValue		rv;
						switch (PA_GetVariableKind (v))
						{
							case eVK_Unistring:
							{
								PA_Unistring	uni = PA_GetStringVariable (v);
								rv.SetText (RWStr::FromPA (&uni));
								break;
							}
							case eVK_Real:
								rv.SetReal (PA_GetRealVariable (v));
								break;
							case eVK_Longint:
								rv.SetInteger (PA_GetLongintVariable (v));
								break;
							case eVK_Boolean:
								rv.SetBoolean (PA_GetBooleanVariable (v));
								break;
							case eVK_Blob:
							{
								SBlob	data;
								data.Init();
								data.fSize = PA_GetBlobVariable (v, data.fData);
								if (data.fSize > 0)
								{
									data.fData = malloc (data.fSize);
									data.fSize = PA_GetBlobVariable (v, data.fData);
								}
								rv.SetBlob (data, true);
								break;
							}
							case eVK_Picture:
//								SR4DData::GetPictureAsBlobFrom4D (PA_GetPictureVariable (v), grv);
								SR4DData::GetPictureFrom4D (PA_GetPictureVariable (v), rv, false);
								break;
							default:
								result = errInvalidPointerType;
								break;
						}
						PA_ClearVariable (&v);
						if (result == 0)
						{
							if (obj->SetProperty (id, rv))
							{
								if (area != NULL)
								{
									if (obj->GetKind() == PSObject::eObject_Style)
										rep->GetPageComposer()->StyleChanged (static_cast <DMStyle*> (obj));
//									else if (st && st->GetFeatures())
//										rep->GetPageComposer()->StyleChanged (st);
									if (st)
										area->AddUndoSnapshot (st, false);
									else
									{
										if (thisID != id)
											obj->GetProperty (thisID, rv);
										if (area->IsRecordingUndo())
											result = area->AddUndoProperty (obj, thisID, oldrv, rv);
									}
									rep->Modified();
								}
							}
							else
								result = errGenericError;
						}
					}
					else
						result = errGenericError;
				}
			}
		}
	}
	catch (long err)
	{
		result = err;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_SetProperty!\n");
		fflush (stdout);
		result = errGenericError;
	}
	
	return result;
}


long RW_GetObjects (long inRepRef, long inRef, FourDTypeID id, PA_Variable &outValue)
{
	long		result = 0;
	DMBase		*obj = NULL;

	if (PA_GetVariableKind (outValue) != eVK_ArrayLongint)
		return errInvalidArrayType;

	try
	{
		DMReport	*rep = DMReport::GetReportObject (inRepRef);
		if (rep == NULL)
			result = errInvalidReportRef;
		else
		{
			obj = rep->GetObject (inRef);
			if (obj == NULL)
				result = errInvalidObjectRef;
			else
			{
				std::unique_ptr<PSObjList>	objs (obj->GetObjects (id));
				if (objs.get() == NULL)
					result = errInvalidRequest;
				else
				{
					PA_ResizeArray (&outValue, objs->size());
					for (size_t i = 0; i < objs->size(); i++)
					{
						PA_SetLongintInArray (outValue, i + 1, ((*objs)[i])->GetInternalID() );
					}
				}
			}
		}
	}
	catch (long err)
	{
		result = err;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_GetObjects!\n");
		fflush (stdout);
		result = errGenericError;
	}

	return result;
}


long RW_NewObject (long inRepRef, long &outRef, FourDTypeID id, long inParent)
{
	long		result = 0;
	DMBase		*obj = NULL;

	try
	{
//		DMReport	*rep = DMReport::GetReportOfObject (inParent);
		DMReport	*rep = DMReport::GetReportObject (inRepRef);
		if (rep == NULL)
			result = errInvalidReportRef;
		else
		{
			obj = rep->CreateObject (id, inParent, RWXmlNode());
			outRef = obj ? obj->GetInternalID() : 0;
			if (obj)
			{
				if (rep->GetPageComposer() != NULL)
				{
					if (static_cast <DMArea*> (rep)->IsRecordingUndo())
						result = static_cast <DMArea*> (rep)->AddUndoCreate (obj);
					rep->Modified();
				}
			}
		}
	}
	catch (long err)
	{
		result = err;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_NewObject!\n");
		fflush (stdout);
		result = errGenericError;
		if (obj)
			delete obj;
	}

	return result;
}


long RW_DeleteObject (long inRepRef, long &ioRef)
{
	long		result = 0;

	try
	{
//		DMBase	*obj = DMReport::GetReportObject (ioRef);
		DMReport	*rep = DMReport::GetReportObject (inRepRef);
		if (rep == NULL)
			result = errInvalidReportRef;
		else
		{
			DMBase	*obj = rep->GetObject (ioRef);
			if (obj == NULL || dynamic_cast <DMArea*> (obj) != NULL)	// must not destoy area!
				result = errInvalidReportRef;
			else
			{
				if (rep->RemoveObject (obj))
				{
					ioRef = 0;
					rep->Modified();
				}
			}
		}
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_DeleteObject!\n");
		fflush (stdout);
		result = errGenericError;
	}

	return result;
}


