long RW_NewObjectFromXML (long inRepRef, long &outRef, CText &inXML, long inParent)
{
	long		result = 0;
	DMBase		*obj = NULL;
	
	try
	{
		DMReport	*rep = DMReport::GetReportObject (inRepRef);
		if (rep == NULL)
			result = errInvalidReportRef;
		else
		{
			RWXmlDocument	xml;
			result = LoadSourceXML (xml, inXML, false);
			if (result == noErr)
			{
				obj = rep->CreateObject (xml.Root(), inParent);
				if (obj)
				{
					if (rep->GetPageComposer() != NULL)
					{
						if (static_cast <DMArea*> (rep)->IsRecordingUndo())
							result = static_cast <DMArea*> (rep)->AddUndoCreate (obj);
						rep->Modified();
					}
					outRef = obj->GetInternalID();
				}
			}
		}
	}
	catch (long err)
	{
		result = err;
	}
	catch (...)
	{
		printf ("\nUncaught exception in RW_NewObjectFromXML!\n");
		fflush (stdout);
		result = errGenericError;
		if (obj)
			delete obj;
	}
	
	return result;
}


